log_files = sorted(glob.glob(os.path.join(log_dir, '*.log')))

best_data = None
best_len = 0
best_source = None

for lf in log_files:
    try:
        with open(lf) as f:
            for line in f:
                try:
                    obj = json.loads(line.strip())
                except:
                    continue
                if obj.get('type') == 'user':
                    msg = obj.get('message', {})
                    contents = msg.get('content', [])
                    if isinstance(contents, list):
                        for c in contents:
                            if isinstance(c, dict) and c.get('type') == 'tool_result':
                                content_val = c.get('content', '')
                                if not isinstance(content_val, str):
                                    continue
                                if 'kl_30pct_s42' not in content_val:
                                    continue
                                try:
                                    result_obj = json.loads(content_val)
                                    inner = json.loads(result_obj['result'])
                                    stdout = inner['data']['stdout']
                                    # Try to parse as JSON
                                    if stdout.strip().startswith('{'):
                                        try:
                                            data = json.loads(stdout)
                                            # Check it has our keys
                                            if 'kl_30pct_s42' in data and isinstance(data['kl_30pct_s42'], dict):
                                                total_points = sum(len(v.get('steps',[])) for v in data.values() if isinstance(v, dict))
                                                if total_points > best_len:
                                                    best_len = total_points
                                                    best_data = data
                                                    best_source = os.path.basename(lf)
                                        except json.JSONDecodeError:
                                            pass
                                except:
                                    pass
    except:
        pass

if best_data:
    print(f"Best data from: {best_source}, total points: {best_len}")
    for k, v in best_data.items():
        if isinstance(v, dict) and 'steps' in v:
            print(f"  {k}: {len(v['steps'])} points, steps {v['steps'][0]}-{v['steps'][-1]}")
    with open('/tmp/lambda_sparsity_curves_best.json', 'w') as out:
        json.dump(best_data, out, indent=2)
    print("Saved to /tmp/lambda_sparsity_curves_best.json")
else:
    print("No full data found in any log")
